import { useEffect, useState } from "react";

function MarksReport() {
  const [students, setStudents] = useState([]);
  const [marks, setMarks] = useState({});
  const [subjects, setSubjects] = useState([]); // [{name, total}]

  useEffect(() => {
    const studentsList = JSON.parse(localStorage.getItem("students")) || [];
    const marksData = JSON.parse(localStorage.getItem("marks")) || {};
    const subjectsData = JSON.parse(localStorage.getItem("subjects")) || [];

    setStudents(studentsList);
    setMarks(marksData);
    setSubjects(subjectsData);
  }, []);

  return (
    <div style={{ padding: "20px" }}>
      <h2>Student Report Card</h2>

      {students.length === 0 ? (
        <p>No students found</p>
      ) : (
        <table border="1" cellPadding="8" style={{ borderCollapse: "collapse", width: "100%" }}>
          <thead>
            <tr style={{ background: "#f0f0f0" }}>
              <th>Student Name</th>
              <th>Roll</th>
              {subjects.map(subj => (
                <th key={subj.name}>{subj.name} (Max: {subj.total})</th>
              ))}
              <th>Total Obtained</th>
              <th>Total Max</th>
              <th>Percentage</th>
            </tr>
          </thead>
          <tbody>
            {students.map(student => {
              const studentMarks = marks[student.id] || {};
              const totalObtained = subjects.reduce(
                (acc, subj) => acc + (Number(studentMarks[subj.name]) || 0),
                0
              );
              const totalMax = subjects.reduce((acc, subj) => acc + subj.total, 0);
              const percentage = totalMax > 0 ? ((totalObtained / totalMax) * 100).toFixed(2) : 0;

              return (
                <tr key={student.id}>
                  <td>{student.name}</td>
                  <td>{student.roll}</td>
                  {subjects.map(subj => (
                    <td key={subj.name}>{studentMarks[subj.name] || 0}</td>
                  ))}
                  <td>{totalObtained}</td>
                  <td>{totalMax}</td>
                  <td>{percentage}%</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default MarksReport;
